\set ON_ERROR_STOP on
BEGIN;
DO $py_phase1$
DECLARE
  v_course bigint;
  n integer;
  r record;
  item jsonb;
  actual_title text;
BEGIN
  SELECT course_id INTO v_course FROM lms.curated_courses WHERE course_key='python';
  IF v_course IS NULL THEN RAISE EXCEPTION 'Python course not found'; END IF;
  SELECT count(*) INTO n FROM lms.lessons l
  JOIN lms.course_sections s ON s.section_id=l.section_id
  WHERE l.course_id=v_course AND s.module_key <> 'intro' AND l.is_published AND NOT l.is_deleted;
  IF n <> 9 THEN RAISE EXCEPTION 'Expected 9 Python content lessons, found %; no change', n; END IF;
  FOR r IN SELECT l.lesson_id, l.title, row_number() OVER (ORDER BY l.lesson_order, l.lesson_id) AS rn
    FROM lms.lessons l JOIN lms.course_sections s ON s.section_id=l.section_id
    WHERE l.course_id=v_course AND s.module_key <> 'intro' AND l.is_published AND NOT l.is_deleted
  LOOP
    SELECT value INTO item FROM jsonb_array_elements($py_material$[{"order": 1, "title": "Giới thiệu Python và lệnh in", "content": "MỤC TIÊU BÀI 01 — Giới thiệu Python và lệnh in\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nViết chương trình giới thiệu bản thân bằng các câu lệnh print(), in mỗi thông tin trên một dòng.\n\nTỰ KIỂM TRA\nChạy chương trình với tên có dấu, tên rỗng và tên dài; phân biệt chuỗi với biểu thức số.\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/introduction.html\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/introduction.html"}, {"order": 2, "title": "Biến và toán tử", "content": "MỤC TIÊU BÀI 02 — Biến và toán tử\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nViết chương trình nhập số lượng và đơn giá, tính thành tiền, giảm giá 10% khi tổng đạt từ 500000 đồng.\n\nTỰ KIỂM TRA\nThử số lượng 0, số lượng 1, giá 499999 và 500000 đồng; kiểm tra kiểu số.\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/introduction.html\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/introduction.html"}, {"order": 3, "title": "Điều kiện if/elif/else", "content": "MỤC TIÊU BÀI 03 — Điều kiện if/elif/else\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nViết chương trình nhập điểm từ 0 đến 10 và phân loại Giỏi (>=8), Khá (>=6.5), Đạt (>=5), Chưa đạt (<5).\n\nTỰ KIỂM TRA\nThử biên 0, 4.99, 5, 6.5, 8, 10; báo nhập sai nếu điểm ngoài [0,10].\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/controlflow.html\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/controlflow.html"}, {"order": 4, "title": "Vòng lặp for và while", "content": "MỤC TIÊU BÀI 04 — Vòng lặp for và while\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nViết chương trình tính tổng các số chẵn từ 1 đến n bằng for, sau đó nhập lại n bằng while cho tới khi là số nguyên dương.\n\nTỰ KIỂM TRA\nThử n = 1, 2, 10, 100 và đầu vào âm; đối chiếu kết quả thủ công.\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/controlflow.html\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/controlflow.html"}, {"order": 5, "title": "Hàm trong Python", "content": "MỤC TIÊU BÀI 05 — Hàm trong Python\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nViết hàm tinh_trung_binh(danh_sach_diem) trả về điểm trung bình; trả về None khi danh sách rỗng.\n\nTỰ KIỂM TRA\nThử [] , [10], [5,7,9] và dữ liệu có điểm ngoài 0..10; giải thích tham số và return.\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/controlflow.html#defining-functions\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/controlflow.html#defining-functions"}, {"order": 6, "title": "Chuỗi và thao tác chuỗi", "content": "MỤC TIÊU BÀI 06 — Chuỗi và thao tác chuỗi\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nViết chương trình chuẩn hóa họ tên: bỏ khoảng trắng đầu/cuối, giảm khoảng trắng lặp, in họ tên viết hoa chữ cái đầu.\n\nTỰ KIỂM TRA\nThử chuỗi rỗng, nhiều khoảng trắng, tên có dấu tiếng Việt và tên chỉ có một từ.\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/introduction.html#text\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/introduction.html#text"}, {"order": 7, "title": "List và Tuple", "content": "MỤC TIÊU BÀI 07 — List và Tuple\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nNhập danh sách điểm của lớp; in điểm cao nhất, thấp nhất, trung bình và danh sách điểm đạt >=5; so sánh list với tuple.\n\nTỰ KIỂM TRA\nThử danh sách rỗng, 1 điểm, các điểm trùng nhau và dữ liệu biên.\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/datastructures.html\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/datastructures.html"}, {"order": 8, "title": "Dictionary và Module", "content": "MỤC TIÊU BÀI 08 — Dictionary và Module\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nDùng dictionary lưu mã học viên và điểm. Viết chức năng tìm theo mã, thêm học viên mới, cập nhật điểm; tách xử lý vào module riêng.\n\nTỰ KIỂM TRA\nThử mã tồn tại/không tồn tại, thêm mã trùng và cập nhật điểm; giải thích import.\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/modules.html\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/modules.html"}, {"order": 9, "title": "Class và thao tác tệp", "content": "MỤC TIÊU BÀI 09 — Class và thao tác tệp\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nTạo lớp SinhVien với tên và điểm, phương thức xep_loai(); lưu danh sách ra tệp UTF-8 bằng with open(...), sau đó đọc lại.\n\nTỰ KIỂM TRA\nThử tệp rỗng, tên có dấu, đường dẫn không tồn tại, điểm ngoài khoảng; không dùng dữ liệu cá nhân thật.\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/classes.html\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/classes.html"}]$py_material$::jsonb) AS value
       WHERE (value->>'order')::integer = r.rn;
    actual_title:=regexp_replace(r.title, '^\s*[0-9]+\s*[.·:-]*\s*', '');
    IF item IS NULL OR lower(trim(actual_title)) <> lower(trim(item->>'title')) THEN
      RAISE EXCEPTION 'Lesson % unexpected title: % (wanted %)', r.rn,r.title,item->>'title';
    END IF;
  END LOOP;
  FOR r IN SELECT l.lesson_id, l.title, row_number() OVER (ORDER BY l.lesson_order, l.lesson_id) AS rn
    FROM lms.lessons l JOIN lms.course_sections s ON s.section_id=l.section_id
    WHERE l.course_id=v_course AND s.module_key <> 'intro' AND l.is_published AND NOT l.is_deleted
  LOOP
    SELECT value INTO item FROM jsonb_array_elements($py_material$[{"order": 1, "title": "Giới thiệu Python và lệnh in", "content": "MỤC TIÊU BÀI 01 — Giới thiệu Python và lệnh in\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nViết chương trình giới thiệu bản thân bằng các câu lệnh print(), in mỗi thông tin trên một dòng.\n\nTỰ KIỂM TRA\nChạy chương trình với tên có dấu, tên rỗng và tên dài; phân biệt chuỗi với biểu thức số.\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/introduction.html\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/introduction.html"}, {"order": 2, "title": "Biến và toán tử", "content": "MỤC TIÊU BÀI 02 — Biến và toán tử\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nViết chương trình nhập số lượng và đơn giá, tính thành tiền, giảm giá 10% khi tổng đạt từ 500000 đồng.\n\nTỰ KIỂM TRA\nThử số lượng 0, số lượng 1, giá 499999 và 500000 đồng; kiểm tra kiểu số.\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/introduction.html\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/introduction.html"}, {"order": 3, "title": "Điều kiện if/elif/else", "content": "MỤC TIÊU BÀI 03 — Điều kiện if/elif/else\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nViết chương trình nhập điểm từ 0 đến 10 và phân loại Giỏi (>=8), Khá (>=6.5), Đạt (>=5), Chưa đạt (<5).\n\nTỰ KIỂM TRA\nThử biên 0, 4.99, 5, 6.5, 8, 10; báo nhập sai nếu điểm ngoài [0,10].\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/controlflow.html\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/controlflow.html"}, {"order": 4, "title": "Vòng lặp for và while", "content": "MỤC TIÊU BÀI 04 — Vòng lặp for và while\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nViết chương trình tính tổng các số chẵn từ 1 đến n bằng for, sau đó nhập lại n bằng while cho tới khi là số nguyên dương.\n\nTỰ KIỂM TRA\nThử n = 1, 2, 10, 100 và đầu vào âm; đối chiếu kết quả thủ công.\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/controlflow.html\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/controlflow.html"}, {"order": 5, "title": "Hàm trong Python", "content": "MỤC TIÊU BÀI 05 — Hàm trong Python\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nViết hàm tinh_trung_binh(danh_sach_diem) trả về điểm trung bình; trả về None khi danh sách rỗng.\n\nTỰ KIỂM TRA\nThử [] , [10], [5,7,9] và dữ liệu có điểm ngoài 0..10; giải thích tham số và return.\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/controlflow.html#defining-functions\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/controlflow.html#defining-functions"}, {"order": 6, "title": "Chuỗi và thao tác chuỗi", "content": "MỤC TIÊU BÀI 06 — Chuỗi và thao tác chuỗi\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nViết chương trình chuẩn hóa họ tên: bỏ khoảng trắng đầu/cuối, giảm khoảng trắng lặp, in họ tên viết hoa chữ cái đầu.\n\nTỰ KIỂM TRA\nThử chuỗi rỗng, nhiều khoảng trắng, tên có dấu tiếng Việt và tên chỉ có một từ.\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/introduction.html#text\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/introduction.html#text"}, {"order": 7, "title": "List và Tuple", "content": "MỤC TIÊU BÀI 07 — List và Tuple\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nNhập danh sách điểm của lớp; in điểm cao nhất, thấp nhất, trung bình và danh sách điểm đạt >=5; so sánh list với tuple.\n\nTỰ KIỂM TRA\nThử danh sách rỗng, 1 điểm, các điểm trùng nhau và dữ liệu biên.\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/datastructures.html\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/datastructures.html"}, {"order": 8, "title": "Dictionary và Module", "content": "MỤC TIÊU BÀI 08 — Dictionary và Module\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nDùng dictionary lưu mã học viên và điểm. Viết chức năng tìm theo mã, thêm học viên mới, cập nhật điểm; tách xử lý vào module riêng.\n\nTỰ KIỂM TRA\nThử mã tồn tại/không tồn tại, thêm mã trùng và cập nhật điểm; giải thích import.\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/modules.html\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/modules.html"}, {"order": 9, "title": "Class và thao tác tệp", "content": "MỤC TIÊU BÀI 09 — Class và thao tác tệp\nNắm được kiến thức cốt lõi của chủ đề và vận dụng vào chương trình Python đơn giản.\n\nTHỰC HÀNH TỰ NGUYỆN\nTạo lớp SinhVien với tên và điểm, phương thức xep_loai(); lưu danh sách ra tệp UTF-8 bằng with open(...), sau đó đọc lại.\n\nTỰ KIỂM TRA\nThử tệp rỗng, tên có dấu, đường dẫn không tồn tại, điểm ngoài khoảng; không dùng dữ liệu cá nhân thật.\n\nGỢI Ý ĐÁNH GIÁ (10 ĐIỂM)\nĐúng yêu cầu và kết quả: 4 điểm; xử lý dữ liệu biên: 2 điểm; có ca kiểm thử và bằng chứng: 2 điểm; giải thích cách làm và nguồn: 2 điểm.\n\nBài thực hành là hoạt động bổ trợ, không dùng để khóa bài học kế tiếp. Để học bài tiếp theo, học viên cần đạt quiz của bài hiện tại.\n\nTÀI LIỆU THAM KHẢO VỀ KIẾN THỨC\nhttps://docs.python.org/3/tutorial/classes.html\nNguồn trên dùng để đối chiếu khái niệm; đề bài thực hành do VEDU biên soạn, không phải trích nguyên văn từ nguồn.", "source": "https://docs.python.org/3/tutorial/classes.html"}]$py_material$::jsonb) AS value
       WHERE (value->>'order')::integer = r.rn;
    UPDATE lms.lessons SET content=item->>'content', updated_at=now() WHERE lesson_id=r.lesson_id
      AND content IS DISTINCT FROM item->>'content';
  END LOOP;
END $py_phase1$;
COMMIT;
